import { ESLint } from "eslint";
import { errorRules } from "@repo/eslint-config/obsidian-scanner";

// The community scanner downgrades every non-security rule to a warning and
// keeps only `errorRules` at error. Remapping results is the only practical way
// to reproduce that: rewriting the severities in the flat config breaks, because
// obsidianmd's blocks inherit plugins through `extends` chains.
const blocks = (ruleId: string | null): boolean =>
  !!ruleId &&
  (Object.prototype.hasOwnProperty.call(errorRules, ruleId) ||
    ruleId.startsWith("eslint-comments/"));

const main = async (): Promise<void> => {
  const eslint = new ESLint({
    overrideConfigFile: "eslint.config.scanner.mjs",
  });
  const results = await eslint.lintFiles(["."]);

  for (const result of results) {
    for (const message of result.messages) {
      // Parse errors have no rule and always block.
      message.severity = message.fatal || blocks(message.ruleId) ? 2 : 1;
    }
    result.errorCount = result.messages.filter((m) => m.severity === 2).length;
    result.warningCount = result.messages.filter((m) => m.severity === 1).length;
    result.fatalErrorCount = result.messages.filter((m) => m.fatal).length;
    result.fixableErrorCount = 0;
    result.fixableWarningCount = 0;
  }

  const formatter = await eslint.loadFormatter("stylish");
  const output = await formatter.format(results);
  if (output) console.log(output);

  const errors = results.reduce((n, r) => n + r.errorCount, 0);
  process.exit(errors > 0 ? 1 : 0);
};

void main();
EOF
