import { defineConfig, globalIgnores } from "eslint/config";
import obsidianmd from "eslint-plugin-obsidianmd";
import eslintComments from "@eslint-community/eslint-plugin-eslint-comments";

// Mirrors the Obsidian community directory scanner, whose errors block the plugin
// from being installable. Ported from obsidianmd/obsidian-workflows src/lint.ts and
// obsidianmd/eslint-plugin docs/configuration.md; re-check both when bumping the plugin.

/** The scanner downgrades every rule except eslint-comments/* to a warning. */
const toWarns = (config) => {
  if (!config) return config;
  if (Array.isArray(config)) return config.map(toWarns);
  const result = { ...config };
  // Recursing into `extends` is load-bearing: most severities live in extended configs.
  if (result.extends) result.extends = toWarns(result.extends);
  if (result.rules) {
    result.rules = Object.fromEntries(
      Object.entries(result.rules).map(([rule, value]) => {
        if (rule.startsWith("eslint-comments/")) return [rule, value];
        if (value === "error" || value === 2) return [rule, "warn"];
        if (Array.isArray(value) && (value[0] === "error" || value[0] === 2)) {
          return [rule, ["warn", ...value.slice(1)]];
        }
        return [rule, value];
      }),
    );
  }
  return result;
};

