import obsidianmd from "eslint-plugin-obsidianmd";
import upstreamConfig from "./obsidian-scanner.upstream.js";

// The scanner config itself is vendored verbatim in obsidian-scanner.upstream.js.
// This file only adds what upstream has no equivalent for: rules for the editor and the test.
export const config = upstreamConfig;

const recommendedRules = Object.assign(
  {},
  ...obsidianmd.configs.recommended.map((block) => block.rules ?? {}),
);

// eslint-comments/* survives the scanner's downgrade untouched, so its options come
// from upstream; hardcoding them once narrowed no-restricted-disable from 12 rules to 2.
const eslintCommentsRules = Object.fromEntries(
  Object.entries(recommendedRules).filter(([rule]) =>
    rule.startsWith("eslint-comments/"),
  ),
);

if (Object.keys(eslintCommentsRules).length === 0) {
  throw new Error(
    "eslint-plugin-obsidianmd no longer sets eslint-comments rules; the editor would silently drop them.",
  );
}

/** The rules the scanner escalates to error, i.e. what blocks a submission. Kept in step with the vendored config by apps/obsidian/test/scannerConfig.test.mts. */
export const errorRules = {
  "no-eval": "error",
  "no-implied-eval": "error",
  "no-unsanitized/method": "error",
  "no-unsanitized/property": "error",
  "obsidianmd/regex-lookbehind": "error",
  "obsidianmd/no-forbidden-elements": "error",
  "obsidianmd/settings-tab/no-manual-html-headings": "error",
  "obsidianmd/settings-tab/no-problematic-settings-headings": "error",
  "obsidianmd/sample-names": "error",
  "obsidianmd/no-sample-code": "error",
  "obsidianmd/platform": "error",
  "obsidianmd/no-plugin-as-component": "error",
  "obsidianmd/detach-leaves": "error",
  "obsidianmd/no-static-styles-assignment": "error",
  "obsidianmd/no-view-references-in-plugin": "error",
  "obsidianmd/no-unsupported-api": "error",
  ...eslintCommentsRules,
};

// Taken from the recommended set rather than a direct dependency, so the editor
// uses the same plugin instances the scanner does.
const recommendedPlugins = Object.assign(
  {},
  ...obsidianmd.configs.recommended.map((block) => block.plugins ?? {}),
);

if (!recommendedPlugins["eslint-comments"]) {
  throw new Error(
    "eslint-plugin-obsidianmd no longer exposes the eslint-comments plugin; editor rules would silently drop it.",
  );
}

export const errorPlugins = {
  obsidianmd,
  "eslint-comments": recommendedPlugins["eslint-comments"],
};

// errorRules minus rules from plugins the app's main config cannot resolve.
export const editorRules = Object.fromEntries(
  Object.entries(errorRules).filter(
    ([rule]) =>
      rule === "no-eval" ||
      Object.keys(errorPlugins).some((p) => rule.startsWith(`${p}/`)),
  ),
);
